BEGIN;
create extension if not exists pgtap with schema extensions;
select plan(2);
DO $test$
DECLARE u uuid:=extensions.gen_random_uuid(); other_u uuid:=extensions.gen_random_uuid(); request_code text:=encode(extensions.gen_random_bytes(32),'hex'); parent_code text; approval jsonb; result jsonb; denied boolean; attempt uuid;
BEGIN
  INSERT INTO auth.users(id,aud,role,is_anonymous,created_at,updated_at) VALUES(u,'authenticated','authenticated',true,now(),now()),(other_u,'authenticated','authenticated',true,now(),now());
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
  denied:=false; BEGIN PERFORM public.claim_parental_consent(request_code,'2026-11-01-v1'); EXCEPTION WHEN insufficient_privilege THEN denied:=true; END; IF NOT denied THEN RAISE EXCEPTION 'Unapproved claim admitted'; END IF;
  approval:=private.approve_parental_consent(request_code,'Synthetic Parent','parent@example.test',encode(extensions.gen_random_bytes(32),'hex'),'synthetic-transaction-only',false,now());
  parent_code:=approval->>'parentControlCode';
  IF parent_code=request_code THEN RAISE EXCEPTION 'Parent and child capabilities must differ'; END IF;
  result:=public.claim_parental_consent(request_code,'2026-11-01-v1');
  IF result->>'onlineAllowed'<>'true' OR result->>'sharingAllowed'<>'false' THEN RAISE EXCEPTION 'Core/sharing not independent'; END IF;
  result:=public.sync_guest_profile('Personal free-form name','custom','#FF0000');
  IF result->>'displayName'='Personal free-form name' OR result->>'avatar'<>'🐨' THEN RAISE EXCEPTION 'Child identity was not generated'; END IF;
  denied:=false; BEGIN PERFORM public.create_friend_room('flags'); EXCEPTION WHEN insufficient_privilege THEN denied:=true; END; IF NOT denied THEN RAISE EXCEPTION 'Friends admitted without sharing consent'; END IF;
  denied:=false; BEGIN PERFORM public.issue_ad_reward_reference(extensions.gen_random_uuid(),'flags'); EXCEPTION WHEN insufficient_privilege THEN denied:=true; END; IF NOT denied THEN RAISE EXCEPTION 'Child ad reference issued'; END IF;
  result:=public.start_daily_attempt('flags');
  SELECT id INTO attempt FROM public.daily_attempts WHERE user_id=u;
  UPDATE public.daily_attempts SET status='completed',current_index=10,completed_at=now() WHERE id=attempt;
  result:=public.get_leaderboard('flags','today',50);
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(result->'entries') e WHERE e->>'userId'=u::text) THEN RAISE EXCEPTION 'Private child score leaked'; END IF;
  denied:=false; BEGIN PERFORM public.register_adult_online_access('2026-11-01-v1'); EXCEPTION WHEN insufficient_privilege THEN denied:=true; END; IF NOT denied THEN RAISE EXCEPTION 'Child self-upgraded to adult'; END IF;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',other_u,'role','authenticated')::text,true);
  denied:=false; BEGIN PERFORM public.claim_parental_consent(request_code,'2026-11-01-v1'); EXCEPTION WHEN insufficient_privilege THEN denied:=true; END; IF NOT denied THEN RAISE EXCEPTION 'Approval reused by other identity'; END IF;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
  denied:=false; BEGIN PERFORM public.parent_consent_control(request_code,'review'); EXCEPTION WHEN insufficient_privilege THEN denied:=true; END; IF NOT denied THEN RAISE EXCEPTION 'Child request code accessed parent controls'; END IF;
  result:=public.parent_consent_control(parent_code,'review');
  IF result->'data'->'profile'->>'user_id'<>u::text THEN RAISE EXCEPTION 'Parent export missing own profile'; END IF;
  PERFORM public.parent_consent_control(parent_code,'sharing',true);
  result:=public.get_leaderboard('flags','today',50);
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(result->'entries') e WHERE e->>'userId'=u::text) THEN RAISE EXCEPTION 'Opt-in score not visible'; END IF;
  result:=public.create_friend_room('flags');
  PERFORM public.parent_consent_control(parent_code,'withdraw');
  IF EXISTS(SELECT 1 FROM private.friend_rooms WHERE host_user_id=u) THEN RAISE EXCEPTION 'Withdrawn room remains'; END IF;
  denied:=false; BEGIN PERFORM public.get_daily_state('flags'); EXCEPTION WHEN insufficient_privilege THEN denied:=true; END; IF NOT denied THEN RAISE EXCEPTION 'Withdrawn child can access online game'; END IF;
  result:=public.parent_consent_control(parent_code,'delete');
  IF result->>'deleteUserId'<>u::text OR EXISTS(SELECT 1 FROM public.guest_profiles WHERE user_id=u) OR EXISTS(SELECT 1 FROM public.daily_attempts WHERE user_id=u) THEN RAISE EXCEPTION 'Child deletion incomplete'; END IF;
  IF EXISTS(SELECT 1 FROM private.online_access WHERE user_id=u) THEN RAISE EXCEPTION 'Deleted permission remains'; END IF;
END $test$;
select pass('parental consent isolation, sharing, withdrawal and deletion assertions passed');
DO $retention$
DECLARE u uuid:=extensions.gen_random_uuid(); code text:=encode(extensions.gen_random_bytes(32),'hex'); a jsonb;
BEGIN
  INSERT INTO auth.users(id,aud,role,is_anonymous,created_at,updated_at) VALUES(u,'authenticated','authenticated',true,now(),now());
  a:=private.approve_parental_consent(code,'Retention QA','parent@example.test',encode(extensions.gen_random_bytes(32),'hex'),'synthetic-retention-test',false,now());
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
  PERFORM public.claim_parental_consent(code,'2026-11-01-v1');
  PERFORM public.sync_guest_profile('Ignored Name','●','#2D9CDB');
  UPDATE private.parental_consents SET expires_at=now()-interval '31 days' WHERE id=(a->>'consentId')::uuid;
  PERFORM private.expire_parental_consents();
  IF EXISTS(SELECT 1 FROM auth.users WHERE id=u) OR EXISTS(SELECT 1 FROM public.guest_profiles WHERE user_id=u) THEN RAISE EXCEPTION 'Expired child data was not deleted'; END IF;
  IF NOT EXISTS(SELECT 1 FROM private.parental_consents WHERE id=(a->>'consentId')::uuid AND status='deleted' AND user_id IS NULL) THEN RAISE EXCEPTION 'Proof cleanup was not scheduled'; END IF;
  UPDATE private.parental_consents SET proof_cleanup_due_at=now()-interval '1 hour' WHERE id=(a->>'consentId')::uuid;
  PERFORM private.expire_parental_consents();
  IF EXISTS(SELECT 1 FROM private.parental_consents WHERE id=(a->>'consentId')::uuid) THEN RAISE EXCEPTION 'Expired proof metadata retained'; END IF;
END $retention$;
select pass('expired child accounts and closed evidence metadata are cleaned up');
select * from finish(true);
ROLLBACK;
